FROM (VALUES
  ('Estética: avaliação antes da agulha', 'Objeção real vira manchete e é respondida pelo processo de avaliação.', ARRAY['estetica', 'objecao_na_manchete', 'agendamento', 'padrao', 'objecao', 'avaliacao']::text[], '{"nicho": "estetica", "estilo_visual": "objecao_na_manchete", "situacao": "Pessoa com vontade de fazer um procedimento, com medo de ficar artificial e sem saber o que serve para o caso dela.", "gancho_visual": "A pergunta do comprador entre aspas em letras grandes no topo; embaixo, bloco na cor da marca com a resposta e foto real da profissional na sala de avaliação.", "gancho_verbal": "Vou ficar artificial?", "texto_apoio": "Toda aplicação começa por uma avaliação com a profissional responsável. Você entende o plano antes de decidir.", "mecanismo": "Objeção real vira manchete e é respondida pelo processo de avaliação.", "tecnica": "Objeção como pauta (técnica 10).", "prova_necessaria": "Avaliação realmente oferecida; registro profissional da responsável; foto real e autorizada.", "cta": "Agendar", "destino": "WhatsApp ou agenda online com a avaliação como primeira mensagem.", "objetivo": "agendamento", "o_que_transportar": "A relação que faz funcionar: objeção real vira manchete e é respondida pelo processo de avaliação. Execução no estilo Objeção na manchete.", "o_que_substituir": "Foto, textos, números, preço, prazo e provas pelos reais do cliente. O gancho verbal é exemplo: reescrever com a linguagem do público. O que está entre colchetes só entra confirmado pela equipe.", "riscos_de_politica": "Estilo com risco baixo. Sem promessa de resultado; sem afirmar característica física de quem vê; público 18+.", "limites": "Padrão de estudo E0 da agência: sem veiculação e sem métrica, é hipótese de criativo, não anúncio validado. Só produzir se existir: avaliação realmente oferecida; registro profissional da responsável; foto real e autorizada.", "fonte": "Padrão da agência Aceleriq (Mesa Ads v2, 24/09/2026), derivado de docs/mesa-ads/pesquisa (DOSSIE-CRIATIVOS.md e PESQUISA-V2.md) e de _shared/conhecimento-ads.ts. Sem marca de terceiros e sem veiculação."}'::jsonb),
  ('Estética: quem aplica faz diferença', 'Autoridade ligada à dúvida do comprador (quem faz), não biografia.', ARRAY['estetica', 'rosto_e_olhar', 'mensagens', 'padrao', 'autoridade']::text[], '{"nicho": "estetica", "estilo_visual": "rosto_e_olhar", "situacao": "Público compara preço de procedimento sem saber comparar quem faz.", "gancho_visual": "Close médio da profissional real olhando para a manchete, ambiente claro, selo pequeno com o registro profissional.", "gancho_verbal": "Quem aplica faz toda a diferença", "texto_apoio": "Formação, protocolo e quem responde por você depois. Pergunte antes de escolher.", "mecanismo": "Autoridade ligada à dúvida do comprador (quem faz), não biografia.", "tecnica": "Adaptação por motivação (técnica 17) e confiança pela pessoa real.", "prova_necessaria": "Formação e registro reais da profissional; protocolo de segurança real.", "cta": "Enviar mensagem", "destino": "WhatsApp com a mensagem pronta: quero saber quem faz e como é.", "objetivo": "mensagens", "o_que_transportar": "A relação que faz funcionar: autoridade ligada à dúvida do comprador (quem faz), não biografia. Execução no estilo Rosto e olhar.", "o_que_substituir": "Foto, textos, números, preço, prazo e provas pelos reais do cliente. O gancho verbal é exemplo: reescrever com a linguagem do público. O que está entre colchetes só entra confirmado pela equipe.", "riscos_de_politica": "Estilo com risco baixo. Sem promessa de resultado; sem comparar com clínica nomeada.", "limites": "Padrão de estudo E0 da agência: sem veiculação e sem métrica, é hipótese de criativo, não anúncio validado. Só produzir se existir: formação e registro reais da profissional; protocolo de segurança real.", "fonte": "Padrão da agência Aceleriq (Mesa Ads v2, 24/09/2026), derivado de docs/mesa-ads/pesquisa (DOSSIE-CRIATIVOS.md e PESQUISA-V2.md) e de _shared/conhecimento-ads.ts. Sem marca de terceiros e sem veiculação."}'::jsonb),
  ('Estética: bastidor do protocolo', 'Bastidor como prova de cuidado e segurança.', ARRAY['estetica', 'bastidor_real', 'seguidores', 'padrao', 'bastidor']::text[], '{"nicho": "estetica", "estilo_visual": "bastidor_real", "situacao": "Seguidora em potencial quer ver como a clínica trabalha antes de confiar.", "gancho_visual": "Foto real do preparo: materiais lacrados sendo abertos, luvas, bancada limpa, luz natural; manchete em bloco de cor.", "gancho_verbal": "Veja o que acontece antes do procedimento", "texto_apoio": "No perfil mostramos o passo a passo de cada protocolo, sem filtro.", "mecanismo": "Bastidor como prova de cuidado e segurança.", "tecnica": "Resultado demonstrável (técnica 8) pelo processo real.", "prova_necessaria": "Fotos reais do protocolo da clínica.", "cta": "Saiba mais", "destino": "Perfil do Instagram com destaques do protocolo.", "objetivo": "seguidores", "o_que_transportar": "A relação que faz funcionar: bastidor como prova de cuidado e segurança. Execução no estilo Bastidor real.", "o_que_substituir": "Foto, textos, números, preço, prazo e provas pelos reais do cliente. O gancho verbal é exemplo: reescrever com a linguagem do público. O que está entre colchetes só entra confirmado pela equipe.", "riscos_de_politica": "Estilo com risco baixo. Sem agulha em pele de forma chocante; sem sangue; sem resultado prometido.", "limites": "Padrão de estudo E0 da agência: sem veiculação e sem métrica, é hipótese de criativo, não anúncio validado. Só produzir se existir: fotos reais do protocolo da clínica.", "fonte": "Padrão da agência Aceleriq (Mesa Ads v2, 24/09/2026), derivado de docs/mesa-ads/pesquisa (DOSSIE-CRIATIVOS.md e PESQUISA-V2.md) e de _shared/conhecimento-ads.ts. Sem marca de terceiros e sem veiculação."}'::jsonb),
  ('Estética: checklist para escolher a clínica', 'Critério de escolha dado de graça posiciona a clínica como a que cumpre todos.', ARRAY['estetica', 'lista_checklist', 'leads', 'padrao', 'guia', 'isca']::text[], '{"nicho": "estetica", "estilo_visual": "lista_checklist", "situacao": "Pessoa pesquisando clínicas e sem critério para escolher.", "gancho_visual": "Título grande e 4 checks grandes na cor da marca; foto real da recepção num terço do quadro.", "gancho_verbal": "4 perguntas antes de escolher sua clínica", "texto_apoio": "Registro de quem aplica, produto usado, avaliação e retorno. Receba o guia.", "mecanismo": "Critério de escolha dado de graça posiciona a clínica como a que cumpre todos.", "tecnica": "Objeção como pauta (técnica 10) e curiosidade com entrega (técnica 12).", "prova_necessaria": "A clínica cumpre de fato cada item da lista.", "cta": "Cadastre-se", "destino": "Formulário instantâneo que entrega o guia e pergunta o interesse.", "objetivo": "leads", "o_que_transportar": "A relação que faz funcionar: critério de escolha dado de graça posiciona a clínica como a que cumpre todos. Execução no estilo Lista ou checklist.", "o_que_substituir": "Foto, textos, números, preço, prazo e provas pelos reais do cliente. O gancho verbal é exemplo: reescrever com a linguagem do público. O que está entre colchetes só entra confirmado pela equipe.", "riscos_de_politica": "Estilo com risco baixo. Não atacar concorrente; não insinuar insegurança de outras clínicas.", "limites": "Padrão de estudo E0 da agência: sem veiculação e sem métrica, é hipótese de criativo, não anúncio validado. Só produzir se existir: a clínica cumpre de fato cada item da lista.", "fonte": "Padrão da agência Aceleriq (Mesa Ads v2, 24/09/2026), derivado de docs/mesa-ads/pesquisa (DOSSIE-CRIATIVOS.md e PESQUISA-V2.md) e de _shared/conhecimento-ads.ts. Sem marca de terceiros e sem veiculação."}'::jsonb),
  ('Estética: natural é técnica', 'Afirmação contraintuitiva que reposiciona o medo de ficar artificial como falta de técnica.', ARRAY['estetica', 'tipografia_gigante', 'mensagens', 'padrao', 'contraintuitivo']::text[], '{"nicho": "estetica", "estilo_visual": "tipografia_gigante", "situacao": "Público consciente da solução com receio de exagero.", "gancho_visual": "Frase gigante em duas linhas com a palavra técnica na cor de destaque, fundo chapado claro da marca, um instrumento real pequeno sobre a letra.", "gancho_verbal": "Natural é técnica, não sorte", "texto_apoio": "Planejamento feito na avaliação, com a quantidade certa para o objetivo combinado.", "mecanismo": "Afirmação contraintuitiva que reposiciona o medo de ficar artificial como falta de técnica.", "tecnica": "Afirmação contraintuitiva ou objeção como pauta (técnicas 10 e 12) com contraste de escala.", "prova_necessaria": "Método de planejamento real da clínica.", "cta": "Enviar mensagem", "destino": "WhatsApp.", "objetivo": "mensagens", "o_que_transportar": "A relação que faz funcionar: afirmação contraintuitiva que reposiciona o medo de ficar artificial como falta de técnica. Execução no estilo Manchete gigante.", "o_que_substituir": "Foto, textos, números, preço, prazo e provas pelos reais do cliente. O gancho verbal é exemplo: reescrever com a linguagem do público. O que está entre colchetes só entra confirmado pela equipe.", "riscos_de_politica": "Estilo com risco baixo. Sem antes e depois; sem promessa de resultado.", "limites": "Padrão de estudo E0 da agência: sem veiculação e sem métrica, é hipótese de criativo, não anúncio validado. Só produzir se existir: método de planejamento real da clínica.", "fonte": "Padrão da agência Aceleriq (Mesa Ads v2, 24/09/2026), derivado de docs/mesa-ads/pesquisa (DOSSIE-CRIATIVOS.md e PESQUISA-V2.md) e de _shared/conhecimento-ads.ts. Sem marca de terceiros e sem veiculação."}'::jsonb),
